INSERT INTO feature VALUES('literal-reading','checking','Numeric literals read at their expected type','modular-implicits','partial','ordinary',NULL,'A natural literal checked at a type apart from `Integer` is read through the `fromNat` of the one model of the prelude''s `FromNat` whose carrier is that type, `theory FromNat where { sort Carrier : Type; oper fromNat : (n : Integer) --> Carrier; }`. The checker records the reader where the literal stands, so the elaboration, the run and the kernel read the application. A literal at `Integer`, or where nothing states a type, stays the literal, with no reader applied. No reader leaves the literal refused `TypeMismatch`, and two refuse it `LiteralAmbiguous` naming the type. A source''s own `FromNat` lends no reader. `-n` written on a natural literal is one negative literal, read through the `fromNeg` of the prelude''s `FromNeg` at its magnitude `n`, and primitive at `Integer`, a value definition''s included. A bare fraction is one exact decimal, and `-d` written on one a negative decimal: at `f64` it stands as the float it rounds to, through no reader, and elsewhere it is read through the `fromDecimal` of the prelude''s `FromDecimal` at its digits and exponent, `1.25` as `fromDecimal(125, -2)`. With no reader a decimal is refused `TypeMismatch` as an `f64`, and where nothing states a type it is refused `NotSynthesisable`. A literal a reader reads, written as a definition''s own value, stands as what the reader''s pure call returns, and a read of the definition runs the call. A reader carrying a constraint is owed.','surface-lowering core-checker core-term core-incremental surface-diagnostics surface-dispatcher','corpus/ledger/features/literal-reading.gandr corpus/ledger/diagnostics/LiteralAmbiguous.gandr corpus/pathological/basics/fractions.gandr corpus/model/basics/literal-in-value.gandr','corpus/ledger/features/literal-reading.gandr','#4733');
